package com.cestasdamel.erp.controller;
import com.cestasdamel.erp.dto.Requests.*; import com.cestasdamel.erp.dto.Responses.*; import com.cestasdamel.erp.service.CatalogService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequiredArgsConstructor public class CatalogController {private final CatalogService service;
 @GetMapping("/products") List<ProductView> products(){return service.products();}@PostMapping("/products") ResponseEntity<ProductView> product(@Valid @RequestBody ProductInput r){return ResponseEntity.status(201).body(service.saveProduct(null,r));}@PutMapping("/products/{id}") ProductView product(@PathVariable Long id,@Valid @RequestBody ProductInput r){return service.saveProduct(id,r);}
 @GetMapping("/materials") List<MaterialView> materials(){return service.materials();}@PostMapping("/materials") ResponseEntity<MaterialView> material(@Valid @RequestBody MaterialInput r){return ResponseEntity.status(201).body(service.saveMaterial(null,r));}@PutMapping("/materials/{id}") MaterialView material(@PathVariable Long id,@Valid @RequestBody MaterialInput r){return service.saveMaterial(id,r);}
 @GetMapping("/baskets") List<BasketView> baskets(){return service.baskets();}@GetMapping("/baskets/{id}") BasketView basket(@PathVariable Long id){return service.basket(id);}@PostMapping("/baskets") ResponseEntity<BasketView> basket(@Valid @RequestBody BasketInput r){return ResponseEntity.status(201).body(service.saveBasket(null,r));}@PutMapping("/baskets/{id}") BasketView basket(@PathVariable Long id,@Valid @RequestBody BasketInput r){return service.saveBasket(id,r);}
}
